lemma affineComb_line [AddCommMonoid A] [Module F A] {s : ℕ}
    (U : Fin (s + 1) → (ι → A)) (v lam : Fin s → F) (t : F) :
    affineComb U (v + t • lam) = affineComb U v + t • (linComb U lam)

lemma pick_subset_card_eq_of_ne {s : Finset α} {n : ℕ}
    (h : pickSubset s n ≠ s) :
  (pickSubset s n).card = n

lemma pick_subset_eq_of_card_pick_subset_lt {s : Finset α} {n : ℕ}
    (h : (s.pickSubset n).card < n) :
  pickSubset s n = s

lemma pick_subset_eq_s_of_card_le_n {s : Finset α} {n : ℕ}
    (h : s.card ≤ n) :
  pickSubset s n = s

theorem block_eq_of_flattenBlocks_eq {blocks width : Nat}
    {xs ys : PolyVec (PolyVec P width) blocks}
    (h : flattenBlocks xs = flattenBlocks ys) (i : Fin blocks) :
    xs i = ys i

@[simp] theorem flattenBlocks_apply {blocks width : Nat}
    (xs : PolyVec (PolyVec P width) blocks) (i : Fin blocks) (j : Fin width) :
    flattenBlocks xs (finProdFinEquiv (i, j)) = xs i j

theorem scalarVecMul_mul_ne_of_ne {cols : ℕ} {c d : P} {v w : PolyVec P cols}
    (hc : IsUnit c) (hd : IsUnit d) (hvw : v ≠ w) :
    (c * d) •ᵥ v ≠ (d * c) •ᵥ w

lemma pow_card_pow_eq_mul {K : Type*} [CommRing K] [Algebra F K] {ω : F} {x : K}
    (hx : x ^ (Fintype.card F - 1) = algebraMap F K ω) (i : ℕ) :
    x ^ (Fintype.card F ^ i) = algebraMap F K (ω ^ i) * x

theorem X_pow_card_sub_one_sub_C_irreducible {ω : F}
    (hω : orderOf ω = Fintype.card F - 1) :
    Irreducible ((X : F[X]) ^ (Fintype.card F - 1) - C ω)

lemma folding_polynomial_eq_map_of_f_degree_lt_q_degree {q f : F[X]}
    (h : f.degree < q.degree) :
    foldingPolynomial q f = Polynomial.map C f

theorem IsPrimitive.separable_map_fractionField_iff [IsGCDMonoid R] {p : R[X]}
    (hprim : p.IsPrimitive) (hp : Irreducible p) :
    (p.map (algebraMap R K)).Separable ↔ p.derivative ≠ 0

lemma indicator_degree_lt_of_pos_subset_neg {pos neg : Finset F}
    (h : pos ⊆ neg) :
  (indicator pos neg).degree < neg.card

lemma indicator_eq_0_on_neg_sub_pos {pos neg : Finset F} {x : F}
    (h_pos : x ∈ neg \ pos) :
  (indicator pos neg).eval x = 0

lemma indicator_eq_1_on_pos {pos neg : Finset F} {x : F}
    (h_pos : x ∈ pos) :
  (indicator pos neg).eval x = 1

lemma indicator_natDegree_lt_of_neg_nonempty {pos neg : Finset F}
    (h : neg.Nonempty) :
  (indicator pos neg).natDegree < (pos ∪ neg).card

lemma indicator_natDegree_lt_of_pos_nonempty {pos neg : Finset F}
    (h : pos.Nonempty) :
  (indicator pos neg).natDegree < (pos ∪ neg).card

lemma indicator_ne_zero_of_pos_nonempty {pos neg : Finset F}
    (h : pos.Nonempty) :
  indicator pos neg ≠ 0

lemma singleton_indicator_degree_lt_of_mem {S : Finset F}
    (h : x ∈ S) :
  (singletonIndicator x S).degree < S.card

lemma singleton_indicator_eval_eq_zero_of_mem_sdiff {S : Finset F} {a : F}
    (h : a ∈ S \ {x}) :
  (singletonIndicator x S).eval a = 0

lemma singleton_indicator_natDegree_lt_of_mem {S : Finset F}
    (h : x ∈ S) :
  (singletonIndicator x S).natDegree < S.card

lemma irreducible_monicizeRatFunc {F : Type} [Field F] {H : Polynomial (Polynomial F)}
    (hHdeg : 0 < H.natDegree) :
