theorem coeff_divByMonic_X_pow_add_one [Nontrivial R] {d : ℕ} (hd : 0 < d) {p : R[X]}
    (hp : p.natDegree < 2 * d) (k : ℕ) :
    (p /ₘ (X ^ d + 1)).coeff k = p.coeff (d + k)

theorem divByMonic_X_pow_add_one [Nontrivial R] {d : ℕ} (hd : 0 < d) {p : R[X]}
    (hp : p.natDegree < 2 * d) :
    p /ₘ (X ^ d + 1) = ∑ k ∈ Finset.range d, (monomial k) (p.coeff (d + k))

lemma eq_of_eval_eq_degree {p q : 𝔽[X]} {n : ℕ}
    (hp : p.degree < .some n) (hq : q.degree < .some n) (s : Finset 𝔽) :
    s.card ≥ n → (∀ x ∈ s, p.eval x = q.eval x) → p = q

lemma eq_of_eval_eq_natDegree {p q : 𝔽[X]} {n : ℕ}
    (hp : p.natDegree < n) (hq : q.natDegree < n) (s : Finset 𝔽) :
    s.card ≥ n → (∀ x ∈ s, p.eval x = q.eval x) → p = q

